struct timespec *timespec_store(struct timespec *ts, usec_t u)  { /* <=== timespec_store */ 
        assert(ts);

        if (u == USEC_INFINITY) {
                ts->tv_sec = (time_t) -1;
                ts->tv_nsec = (long) -1;
                return ts;
        }

        ts->tv_sec = (time_t) (u / USEC_PER_SEC);
        ts->tv_nsec = (long int) ((u % USEC_PER_SEC) * NSEC_PER_USEC);

        return ts;
}

noreturn void log_assert_failed(const char *text, const char *file, int line, const char *func) { /* <=== log_assert_failed */ 
